SELECT currency, rate_date, rate_to_eur, source FROM currency_rates WHERE currency = 'CZK' AND rate_date BETWEEN '2026-10-12' AND '2026-10-20' ORDER BY rate_date
SELECT lb.tender_id, lb.lot_id, c.cursor, c.version_seq, c.op, c.changed_at FROM tender_version_lots lb CROSS JOIN changes c WHERE lb.tender_id = 878700 AND lb.seq = 360 AND c.entity_kind = 'lot' AND c.entity_id = lb.lot_id AND c.changed_at >= 1792281600 UNION ALL SELECT lb.tender_id, lb.lot_id, c.cursor, c.version_seq, c.op, c.changed_at FROM tender_version_lots lb CROSS JOIN changes c WHERE lb.tender_id = 1139127 AND lb.seq = 3 AND c.entity_kind = 'lot' AND c.entity_id = lb.lot_id AND c.changed_at >= 1792281600 UNION ALL SELECT c.entity_id, NULL, c.cursor, c.version_seq, c.op, c.changed_at FROM changes c WHERE c.entity_kind = 'tender' AND c.entity_id = 878700 AND c.changed_at >= 1792281600 UNION ALL SELECT c.entity_id, NULL, c.cursor, c.version_seq, c.op, c.changed_at FROM changes c WHERE c.entity_kind = 'tender' AND c.entity_id = 1139127 AND c.changed_at >= 1792281600 LIMIT 300
